function playerInfoValue(id){try{return PlayerInfo.read(TeamStore,id);}catch{return PlayerInfo.normalize();}}
function footPair(info){return `<div class="foot-pair" aria-label="왼발과 오른발 능력치">${[['left','왼발'],['right','오른발']].map(([side,label])=>{const primary=info.dominant===side||info.dominant==='both',role=info.dominant?(primary?'주발':'약발'):'미입력',score=info[side]??'—';return `<div class="foot-item ${primary?'primary-foot':'weak-foot'}"><svg viewBox="0 0 42 72" role="img" aria-label="${label} ${role} ${score}${score==='—'?'':'점'}"><g ${side==='right'?'transform="translate(42 0) scale(-1 1)"':''}><path d="M25 3C34 2 39 10 38 21C37 30 33 37 32 45L32 58C32 66 28 70 23 70C16 70 12 65 10 57L5 36C2 24 5 12 14 6C18 4 22 3 25 3Z"/></g><text class="boot-score" x="21" y="48" text-anchor="middle">${score}</text></svg><span>${label}</span><small>${role}</small></div>`;}).join('')}</div>`;}
function playerStarRows(info){return `<div class="player-star-rows">${[['staminaStars','스태미너'],['skillStars','개인기']].map(([key,label])=>{const value=info[key];return `<div class="player-star-row"><span>${label}</span><div class="player-stars" role="img" aria-label="${label} ${value==null?'미입력':value+' / 5점'}">${[0,1,2,3,4].map(i=>`<span class="rating-star" aria-hidden="true" style="--star-fill:${Math.max(0,Math.min(1,(value||0)-i))*100}%"><span><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m12 2.5 2.9 6 6.6 1-4.8 4.6 1.1 6.6-5.8-3.1-5.8 3.1 1.1-6.6-4.8-4.6 6.6-1Z"/></svg></span><i><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m12 2.5 2.9 6 6.6 1-4.8 4.6 1.1 6.6-5.8-3.1-5.8 3.1 1.1-6.6-4.8-4.6 6.6-1Z"/></svg></i></span>`).join('')}</div><small>${value==null?'미입력':value+' / 5'}</small></div>`;}).join('')}</div>`;}
function playerInfoPanel(p){const info=playerInfoValue(p.id);return `<section class="player-info-panel" aria-label="신체 및 주발 정보"><div class="player-info-heading"><h3>신체 · 주발 정보</h3><button class="text-btn" data-action="player-info-edit" data-id="${p.id}">정보 입력 / 수정 <svg class="ui-direction" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 17 17 7M7 7h10v10"/></svg></button></div><div class="player-info-summary"><dl><div><dt>키</dt><dd>${info.height??'—'} <small>cm</small></dd></div><div><dt>몸무게</dt><dd>${info.weight??'—'} <small>kg</small></dd></div></dl>${footPair(info)}</div><p class="foot-legend"><span>양발 능력치 1–5</span></p>${playerStarRows(info)}</section>`;}
function playerInfoEditor(id){const p=getPlayer(id),info=playerInfoValue(id);if(!p)return;closeModal();modal('신체 · 주발 정보',`<form id="player-info-form" data-player-id="${p.id}"><p class="body-editor-player">${esc(p.name)} <span>${p.pos}</span></p><div class="body-input-grid"><label for="player-height">키 <span>cm</span><input id="player-height" name="height" type="number" inputmode="decimal" min="50" max="250" step="0.1" value="${info.height??''}" placeholder="미입력"></label><label for="player-weight">몸무게 <span>kg</span><input id="player-weight" name="weight" type="number" inputmode="decimal" min="20" max="300" step="0.1" value="${info.weight??''}" placeholder="미입력"></label></div><label class="dominant-label" for="player-dominant">주발</label><select id="player-dominant" name="dominant">${[['','미입력'],['left','왼발'],['right','오른발'],['both','양발']].map(([value,label])=>`<option value="${value}" ${info.dominant===value?'selected':''}>${label}</option>`).join('')}</select><div id="foot-preview" aria-live="polite">${footPair(info)}</div><div class="body-input-grid">${[['left','왼발'],['right','오른발']].map(([side,label])=>`<label for="player-${side}">${label} 능력치<select id="player-${side}" name="${side}" aria-label="${label} 능력치"><option value="">미입력</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${info[side]===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}</div><p class="foot-editor-note">각 발의 능력치를 1부터 5까지 입력하세요.<br>주발은 형광색, 약발은 회색으로 표시됩니다.<br>양발을 선택하면 두 발 모두 형광색입니다.</p><section class="player-stars-editor"><h3>스태미너 · 개인기 별점</h3><div id="player-star-preview" aria-live="polite">${playerStarRows(info)}</div><div class="body-input-grid">${[['staminaStars','스태미너'],['skillStars','개인기']].map(([key,label])=>`<label for="player-${key}">${label} 별점<select id="player-${key}" name="${key}" aria-label="${label} 별점"><option value="">미입력</option>${Array.from({length:10},(_,i)=>(i+1)/2).map(n=>`<option value="${n}" ${info[key]===n?'selected':''}>${n} / 5</option>`).join('')}</select></label>`).join('')}</div><p class="foot-editor-note">0.5점 단위로 직접 입력합니다.<br>세부 능력치의 예시 수치와 별도로 저장됩니다.</p></section><p class="prototype-note">관리자가 저장한 정보는 모든 기기에 공유됩니다.</p><p id="player-info-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn secondary" data-action="player-info-cancel" data-id="${p.id}">취소</button><button type="submit" class="btn primary">저장</button></div></form>`);}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;if(target.dataset.action==='player-info-edit')playerInfoEditor(Number(target.dataset.id));if(target.dataset.action==='player-info-cancel')playerModal(Number(target.dataset.id));});
document.addEventListener('change',event=>{const form=event.target.closest('#player-info-form');if(!form)return;const data=new FormData(form);document.querySelector('#foot-preview').innerHTML=footPair({dominant:data.get('dominant'),left:data.get('left')||null,right:data.get('right')||null});document.querySelector('#player-star-preview').innerHTML=playerStarRows({staminaStars:data.get('staminaStars')?Number(data.get('staminaStars')):null,skillStars:data.get('skillStars')?Number(data.get('skillStars')):null});});
document.addEventListener('submit',event=>{const form=event.target;if(form.id!=='player-info-form')return;event.preventDefault();const id=Number(form.dataset.playerId);let value;try{value=PlayerInfo.normalize(Object.fromEntries(new FormData(form)));}catch(error){document.querySelector('#player-info-error').textContent=error.message;return;}try{PlayerInfo.write(TeamStore,id,value);}catch{document.querySelector('#player-info-error').textContent='저장하지 못했습니다. 브라우저의 저장 공간 설정을 확인해 주세요.';return;}playerModal(id);toast('신체 · 주발 정보를 저장했습니다.');});
